const HANDOVER_LIFETIME = 7 * 24 * 60 * 60 * 1000;

type HandoverRow = typeof ownershipHandovers."'$inferSelect;
function handoverFromRow(row: HandoverRow): OwnershipHandover {
  return {
    ...row,
    orgId: row.orgId as OrgId,
    fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId,
    createdAt: row.createdAt as IsoTimestamp,
    expiresAt: row.expiresAt as IsoTimestamp,
    resolvedAt: row.resolvedAt as IsoTimestamp | null,
  };
}

export async function assertRecordedOwner(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:manage_billing", {
      action: "org:manage_billing", resourceKind: "organization",
      allowed: false, reason: "denied_by_role",
    });
  }
  return org;
}

export async function initiateOwnershipHandover(actor: Actor, orgId: OrgId, toUserId: UserId): Promise<OwnershipHandover> {
  const org = await assertRecordedOwner(actor, orgId);
  if (toUserId === org.ownerId) throw new OwnershipHandoverError("self");
  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") throw new NotFoundError("Member", toUserId);
  const now = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(new Date(new Date(now).getTime() + HANDOVER_LIFETIME));
  const db = getDb();
  const row = db.transaction((tx) => {
    tx.update(ownershipHandovers).set({ status: "expired", resolvedAt: now })
      .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"), lte(ownershipHandovers.expiresAt, now))).run();
    const pending = tx.select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
    if (pending) throw new OwnershipHandoverError("pending_exists");
    const offer = tx.insert(ownershipHandovers).values({ id: newId(), orgId, fromUserId: actor.userId, toUserId, status: "pending", createdAt: now, expiresAt, resolvedAt: null }).returning().get();
    tx.insert(notifications).values({ id: newId(), orgId, recipientId: toUserId, kind: "ownership_handover", title: "Workspace ownership offer", body: `${actor.userId} invited you to take ownership of ${org.name}`, href: "/settings/members", actorId: actor.userId, readAt: null, channels: JSON.stringify(["in_app"]), createdAt: now, updatedAt: now }).run();
    return offer;
  });
  return handoverFromRow(row);
}

export async function getPendingOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  const row = getDb().select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"), gt(ownershipHandovers.expiresAt, toIsoTimestamp(new Date())))).get();
  return row ? handoverFromRow(row) : null;
}

function findActionableOffer(orgId: OrgId, userId: UserId, now: IsoTimestamp): HandoverRow {
  const row = getDb().select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
  if (!row || row.toUserId !== userId) throw new OwnershipHandoverError("nothing_pending");
  if (row.expiresAt <= now) throw new OwnershipHandoverError("expired");
  return row;
}

export async function declineOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const now = toIsoTimestamp(new Date());
  const row = findActionableOffer(orgId, actor.userId, now);
  const updated = getDb().update(ownershipHandovers).set({ status: "declined", resolvedAt: now }).where(eq(ownershipHandovers.id, row.id)).returning().get();
  return handoverFromRow(updated);
}

export async function cancelOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  await assertRecordedOwner(actor, orgId);
  const now = toIsoTimestamp(new Date());
  const row = getDb().select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"), gt(ownershipHandovers.expiresAt, now), eq(ownershipHandovers.fromUserId, actor.userId))).get();
  if (!row) throw new OwnershipHandoverError("nothing_pending");
  const updated = getDb().update(ownershipHandovers).set({ status: "canceled", resolvedAt: now }).where(eq(ownershipHandovers.id, row.id)).returning().get();
  return handoverFromRow(updated);
}

export async function acceptOwnershipHandover(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const now = toIsoTimestamp(new Date());
  const offer = findActionableOffer(orgId, actor.userId, now);
  const db = getDb();
  const changes = db.transaction((tx) => {
    const from = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, offer.fromUserId), isNull(members.archivedAt), eq(members.status, "active"))).get();
    const to = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, offer.toUserId), isNull(members.archivedAt), eq(members.status, "active"))).get();
    const org = tx.select().from(organizations).where(eq(organizations.id, orgId)).get();
    if (!from || !to || !org || org.ownerId !== offer.fromUserId) throw new OwnershipHandoverError("nothing_pending");
    if (to.role !== "owner") tx.update(members).set({ role: "owner", updatedAt: now }).where(eq(members.id, to.id)).run();
    tx.update(organizations).set({ ownerId: to.userId, updatedAt: now }).where(eq(organizations.id, orgId)).run();
    if (from.role === "owner") tx.update(members).set({ role: "admin", updatedAt: now }).where(eq(members.id, from.id)).run();
    tx.update(ownershipHandovers).set({ status: "accepted", resolvedAt: now }).where(eq(ownershipHandovers.id, offer.id)).run();
    return { from, to };
  });
  if (changes.to.role !== "owner") await emit("member.role_changed", { ...actorEnvelope(actor), memberId: changes.to.id as MemberId, from: changes.to.role, to: "owner" });
  if (changes.from.role === "owner") await emit("member.role_changed", { ...actorEnvelope(actor), memberId: changes.from.id as MemberId, from: "owner", to: "admin" });
  await emit("organization.ownership_transferred", { ...actorEnvelope(actor), fromUserId: offer.fromUserId as UserId, toUserId: offer.toUserId as UserId });
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}
